num_triplets = 500 # 50 500 1000
window = 12 # * 5 12
print("window:", window)

# Create an empty array to store the triplets and corresponding t values
triplet_data = np.zeros((num_triplets, 4, *data.shape[1:]), dtype=np.float32) # (1000, 4, 4, 128, 128, 128)
# size, triplets + t, dens + vel, x, y, z
print("triplet_data:", triplet_data.shape)
print("triplet_data type:", triplet_data.dtype)
# input("data")

triplet_idx = 0
with Bar("Loading the data...", max=num_triplets) as bar:
    while triplet_idx < num_triplets:

        # Randomly select triplets
        for i in range(num_triplets):
            print("\n")

            # Randomly select k
            k = np.random.randint(0, data.shape[0] - window)
            # print("k", k)
            # Calculate the valid range for l
            max_l = min(data.shape[0], k + window)
            # print("max_l", max_l)
            # Randomly select l within the valid range
            l = np.random.randint(k + 1 + 1, max_l + 1)
            # print("l", l)
            # Randomly select t between k and l
            t = np.random.randint(k + 1, l)
            # print("t", t)
            
            # k = t - window
            # l = t + window

            # k, t, l = k * member_idx, t * member_idx, l * member_idx
            print(" ", k, t, l)

            triplet_data[triplet_idx, 0] = data[k]
            triplet_data[triplet_idx, 1] = data[t]
            triplet_data[triplet_idx, 2] = data[l]

            # Calculate t value and create mask
            t_value = (t - k) / (l - k)
            mask = np.zeros((1, *data.shape[1:]))
            mask[0] = 1
            triplet_data[triplet_idx, 3] = mask * t_value
            # print("t_mask:", triplet_data[triplet_idx, 3])

            triplet_idx += 1
            bar.next()

print('Triplet data shape:', triplet_data.shape)
print(triplet_data.dtype)
